import{_ as t,a as o,o as r,a4 as a}from"./chunks/framework.-FZumj2l.js";const m=JSON.parse('{"title":"Reporting","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/admin/reporting/index.md","filePath":"api/rest-api/admin/reporting/index.md","lastUpdated":1783079210000}'),d={name:"api/rest-api/admin/reporting/index.md"};function s(i,e,n,p,c,h){return r(),o("div",null,e[0]||(e[0]=[a('<h1 id="reporting" tabindex="-1">Reporting <a class="header-anchor" href="#reporting" aria-label="Permalink to &quot;Reporting&quot;">​</a></h1><p>The Reporting menu returns the deep, dedicated reports behind the admin <strong>Reporting</strong> screens — <strong>Sales</strong>, <strong>Customers</strong> and <strong>Products</strong> — plus an API-only <strong>Overview</strong> convenience aggregation. Each report rolls up a chosen metric over a date window, compared against the previous equal-length window.</p><h2 id="how-a-report-is-selected-—-the-type-argument" tabindex="-1">How a report is selected — the <code>type</code> argument <a class="header-anchor" href="#how-a-report-is-selected-—-the-type-argument" aria-label="Permalink to &quot;How a report is selected — the `type` argument&quot;">​</a></h2><p>Each report page exposes several metrics, and you pick one with the <code>?type=</code> query parameter (e.g. <code>?type=total-sales</code>). Omitting <code>type</code> falls back to that page&#39;s default (the first metric). The <code>statistics</code> payload is the raw aggregate for the chosen <code>type</code>, so its shape varies per metric — branch on <code>type</code> when consuming it.</p><h2 id="the-four-reports" tabindex="-1">The four reports <a class="header-anchor" href="#the-four-reports" aria-label="Permalink to &quot;The four reports&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Report</th><th>What it covers</th><th><code>type</code> values</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/reporting/overview.html">Overview</a></td><td>API-only top-line summary across the store</td><td><code>total-sales</code> (default), <code>total-orders</code>, <code>total-customers</code>, <code>top-selling-products-by-revenue</code></td></tr><tr><td><a href="/api/rest-api/admin/reporting/sales.html">Sales</a></td><td>Revenue, orders, funnel, refunds, tax, shipping, payment methods</td><td><code>total-sales</code> (default) + 8 more</td></tr><tr><td><a href="/api/rest-api/admin/reporting/customers.html">Customers</a></td><td>New customers, traffic, top customers/groups</td><td><code>total-customers</code> (default) + 5 more</td></tr><tr><td><a href="/api/rest-api/admin/reporting/products.html">Products</a></td><td>Sold quantities, wishlists, top sellers, reviews, search terms</td><td><code>total-sold-quantities</code> (default) + 7 more</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Overview has no matching admin screen</p><p>The admin Reporting menu goes straight to Sales / Customers / Products — there is <strong>no</strong> &quot;Overview&quot; screen in the panel. Overview is an API convenience that fetches one top-line number without calling the per-section endpoints.</p></div><h2 id="three-shapes-per-report-—-stats-view-details-export" tabindex="-1">Three shapes per report — Stats, View Details, Export <a class="header-anchor" href="#three-shapes-per-report-—-stats-view-details-export" aria-label="Permalink to &quot;Three shapes per report — Stats, View Details, Export&quot;">​</a></h2><p>Sales / Customers / Products each expose the same metric in three forms:</p><table tabindex="0"><thead><tr><th>Form</th><th>Endpoint suffix</th><th>Shape</th><th>Mirrors</th></tr></thead><tbody><tr><td><strong>Stats</strong></td><td><em>(none)</em> — e.g. <code>/reporting/sales</code></td><td>Rolled-up headline figures (charts/progress)</td><td>the panel summary</td></tr><tr><td><strong>View Details</strong></td><td><code>/view</code></td><td><code>{ columns, records }</code> — the full row-by-row table</td><td>the panel&#39;s <strong>View Details</strong> link</td></tr><tr><td><strong>Export (CSV)</strong></td><td><code>/export?format=csv</code></td><td><code>text/csv</code> attachment</td><td>the <strong>Export</strong> button</td></tr></tbody></table><p><strong>Overview is summary-only</strong> — it has no View Details and no Export.</p><h2 id="date-window" tabindex="-1">Date window <a class="header-anchor" href="#date-window" aria-label="Permalink to &quot;Date window&quot;">​</a></h2><p><code>start</code> / <code>end</code> (<code>YYYY-MM-DD</code>) bound the report and the <code>previous</code> baseline behind each <code>progress</code> percentage — the previous period is the same-length window immediately before <code>start</code>. <code>channel</code> (a channel <strong>code</strong>) scopes the figures to a single storefront channel. <code>dateRange</code> in the response reports the two comparison windows: <code>current</code> is the window you asked for, <code>previous</code> is the equal-length window immediately before it.</p><h2 id="endpoints-in-this-menu" tabindex="-1">Endpoints in this menu <a class="header-anchor" href="#endpoints-in-this-menu" aria-label="Permalink to &quot;Endpoints in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/reporting/overview.html">Overview</a></td><td><code>GET /api/admin/reporting/stats</code></td></tr><tr><td><a href="/api/rest-api/admin/reporting/sales.html">Sales</a></td><td><code>GET /api/admin/reporting/sales</code> (+ <code>/view</code>, <code>/export</code>)</td></tr><tr><td><a href="/api/rest-api/admin/reporting/customers.html">Customers</a></td><td><code>GET /api/admin/reporting/customers</code> (+ <code>/view</code>, <code>/export</code>)</td></tr><tr><td><a href="/api/rest-api/admin/reporting/products.html">Products</a></td><td><code>GET /api/admin/reporting/products</code> (+ <code>/view</code>, <code>/export</code>)</td></tr></tbody></table><p>Reporting is read-only and requires only an admin Bearer token (no permission gate) — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p>',16)]))}const u=t(d,[["render",s]]);export{m as __pageData,u as default};
